# Checks with a set whether some A_i minus some A_j equals X
N, X = map(int, input().split())
A = list(map(int, input().split()))
Aset = set(A)
ok = False
for a in A:
    if (X - a) in Aset and (X - a != a or A.count(a) > 1):
        ok = True
        break
if ok:
    print('Yes')
else:
    print('No')

